import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/highlights.html","title":"高频考点","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"highlights.md"}`),a={name:`highlights.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="高频考点" tabindex="-1"><a class="header-anchor" href="#高频考点"><span>高频考点</span></a></h1><h2 id="第01章-信息化发展" tabindex="-1"><a class="header-anchor" href="#第01章-信息化发展"><span>第01章 信息化发展</span></a></h2><h3 id="高频考点-1" tabindex="-1"><a class="header-anchor" href="#高频考点-1"><span>高频考点</span></a></h3><ol><li><p><strong>信息化的定义和特征</strong></p><ul><li>信息化是培养、发展以计算机为主的智能化工具为代表的新生产力</li><li>特征：综合性、渗透性、创新性、带动性、全球性</li></ul></li><li><p><strong>国家信息化战略</strong></p><ul><li>网络强国战略、大数据战略、&quot;互联网+&quot;行动计划</li><li>战略目标：建设网络强国、数字中国</li></ul></li><li><p><strong>信息系统的组成要素</strong></p><ul><li>人、机、软、数、流五大要素</li><li>功能：输入、处理、输出、存储、控制</li></ul></li></ol><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>人机软数流，输入处理存控制，生老病死全周期</p><hr><h2 id="第02章-信息技术发展" tabindex="-1"><a class="header-anchor" href="#第02章-信息技术发展"><span>第02章 信息技术发展</span></a></h2><h3 id="高频考点-2" tabindex="-1"><a class="header-anchor" href="#高频考点-2"><span>高频考点</span></a></h3><ol><li><p><strong>信息技术发展阶段</strong></p><ul><li>电子管→晶体管→集成电路→大规模集成电路→人工智能</li></ul></li><li><p><strong>云计算服务模式</strong></p><ul><li>IaaS：基础设施即服务</li><li>PaaS：平台即服务</li><li>SaaS：软件即服务</li></ul></li><li><p><strong>大数据特征（5V）</strong></p><ul><li>Volume（数据量大）、Velocity（处理速度快）</li><li>Variety（数据类型多样）、Value（价值密度低）、Veracity（数据真实性）</li></ul></li></ol><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>云大物移智区块，新技引领数字化</p><hr><h2 id="第03章-信息系统治理" tabindex="-1"><a class="header-anchor" href="#第03章-信息系统治理"><span>第03章 信息系统治理</span></a></h2><h3 id="高频考点-3" tabindex="-1"><a class="header-anchor" href="#高频考点-3"><span>高频考点</span></a></h3><ol><li><p><strong>治理与管理的区别</strong></p><ul><li>治理：做正确的事（战略层）</li><li>管理：正确地做事（执行层）</li></ul></li><li><p><strong>COBIT框架</strong></p><ul><li>IT治理的国际标准框架</li><li>提供IT治理的最佳实践指南</li></ul></li><li><p><strong>数据治理核心要素</strong></p><ul><li>数据质量、数据安全、数据生命周期、数据标准</li></ul></li></ol><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>治理定方向，管理抓执行，COBIT定框架</p><hr><h2 id="第04章-信息系统管理" tabindex="-1"><a class="header-anchor" href="#第04章-信息系统管理"><span>第04章 信息系统管理</span></a></h2><h3 id="高频考点-4" tabindex="-1"><a class="header-anchor" href="#高频考点-4"><span>高频考点</span></a></h3><ol><li><p><strong>ITIL服务生命周期</strong></p><ul><li>服务战略、服务设计、服务过渡、服务运营、持续服务改进</li></ul></li><li><p><strong>信息安全三要素（CIA）</strong></p><ul><li>机密性、完整性、可用性</li></ul></li><li><p><strong>IT服务管理核心流程</strong></p><ul><li>事件管理、问题管理、变更管理、配置管理</li></ul></li></ol><h3 id="记忆口诀-3" tabindex="-1"><a class="header-anchor" href="#记忆口诀-3"><span>记忆口诀</span></a></h3><p>战略设计过渡运营持续改，机密完整可用安全三要素</p><hr><h2 id="第05章-信息系统工程" tabindex="-1"><a class="header-anchor" href="#第05章-信息系统工程"><span>第05章 信息系统工程</span></a></h2><h3 id="高频考点-5" tabindex="-1"><a class="header-anchor" href="#高频考点-5"><span>高频考点</span></a></h3><ol><li><p><strong>软件生命周期</strong></p><ul><li>需求分析、系统设计、编码实现、测试验证、运行维护</li></ul></li><li><p><strong>软件开发模型</strong></p><ul><li>瀑布模型、敏捷模型、螺旋模型、V模型</li></ul></li><li><p><strong>系统集成类型</strong></p><ul><li>硬件集成、软件集成、数据集成、网络集成、应用集成</li></ul></li></ol><h3 id="记忆口诀-4" tabindex="-1"><a class="header-anchor" href="#记忆口诀-4"><span>记忆口诀</span></a></h3><p>需设编测维，软件生命全周期，软硬数网应集成</p><hr><h2 id="第06章-项目管理概论" tabindex="-1"><a class="header-anchor" href="#第06章-项目管理概论"><span>第06章 项目管理概论</span></a></h2><h3 id="高频考点-6" tabindex="-1"><a class="header-anchor" href="#高频考点-6"><span>高频考点</span></a></h3><ol><li><p><strong>项目特征</strong></p><ul><li>临时性、独特性、渐进明细、目标导向、资源约束</li></ul></li><li><p><strong>PMBOK十大知识领域</strong></p><ul><li>整合、范围、进度、成本、质量、资源、沟通、风险、采购、干系人</li></ul></li><li><p><strong>五大过程组</strong></p><ul><li>启动、规划、执行、监控、收尾</li></ul></li></ol><h3 id="记忆口诀-5" tabindex="-1"><a class="header-anchor" href="#记忆口诀-5"><span>记忆口诀</span></a></h3><p>整范进成本，质资沟风采干，五大过程组要记全</p><hr><h2 id="第07章-项目立项管理" tabindex="-1"><a class="header-anchor" href="#第07章-项目立项管理"><span>第07章 项目立项管理</span></a></h2><h3 id="高频考点-7" tabindex="-1"><a class="header-anchor" href="#高频考点-7"><span>高频考点</span></a></h3><ol><li><p><strong>立项流程</strong></p><ul><li>项目建议、可行性研究、项目评估、项目审批</li></ul></li><li><p><strong>可行性研究内容</strong></p><ul><li>技术可行性、经济可行性、社会可行性、风险评估</li></ul></li><li><p><strong>招投标流程</strong></p><ul><li>招标公告、资格预审、投标、开标、评标、中标、合同签订</li></ul></li></ol><h3 id="记忆口诀-6" tabindex="-1"><a class="header-anchor" href="#记忆口诀-6"><span>记忆口诀</span></a></h3><p>建议研究评估审批，技术经济社会风险，公告预审投标开标评标中标</p><hr><h2 id="第08章-项目整合管理" tabindex="-1"><a class="header-anchor" href="#第08章-项目整合管理"><span>第08章 项目整合管理</span></a></h2><h3 id="高频考点-8" tabindex="-1"><a class="header-anchor" href="#高频考点-8"><span>高频考点</span></a></h3><ol><li><p><strong>项目章程内容</strong></p><ul><li>项目目的、范围、里程碑、预算、项目经理任命</li></ul></li><li><p><strong>项目管理计划组成</strong></p><ul><li>十大子计划：范围、进度、成本、质量、风险、资源、沟通、采购、干系人、变更</li></ul></li><li><p><strong>整体变更控制流程</strong></p><ul><li>提交、评估、审批、实施、验证、记录</li></ul></li></ol><h3 id="记忆口诀-7" tabindex="-1"><a class="header-anchor" href="#记忆口诀-7"><span>记忆口诀</span></a></h3><p>章程批准项目，计划整合十子项，变更控制六步骤</p><hr><h2 id="第09章-项目范围管理" tabindex="-1"><a class="header-anchor" href="#第09章-项目范围管理"><span>第09章 项目范围管理</span></a></h2><h3 id="高频考点-9" tabindex="-1"><a class="header-anchor" href="#高频考点-9"><span>高频考点</span></a></h3><ol><li><p><strong>范围管理流程</strong></p><ul><li>范围规划、范围定义、WBS分解、范围验证、范围控制</li></ul></li><li><p><strong>WBS分解原则</strong></p><ul><li>完整性、层次性、可管理性、独立性、可交付性</li></ul></li><li><p><strong>范围基准组成</strong></p><ul><li>项目范围说明书、WBS、WBS词典</li></ul></li></ol><h3 id="记忆口诀-8" tabindex="-1"><a class="header-anchor" href="#记忆口诀-8"><span>记忆口诀</span></a></h3><p>工作分解结构清，层层分解到活动，范围基准三部分</p><hr><h2 id="第10章-项目进度管理" tabindex="-1"><a class="header-anchor" href="#第10章-项目进度管理"><span>第10章 项目进度管理</span></a></h2><h3 id="高频考点-10" tabindex="-1"><a class="header-anchor" href="#高频考点-10"><span>高频考点</span></a></h3><ol><li><p><strong>关键路径法</strong></p><ul><li>关键路径是项目中最长的路径，决定项目最短工期</li><li>总浮动时间为零的活动组成关键路径</li></ul></li><li><p><strong>进度压缩方法</strong></p><ul><li>赶工：增加资源缩短工期</li><li>快速跟进：串行改并行</li></ul></li><li><p><strong>活动历时估算方法</strong></p><ul><li>专家判断、类比估算、参数估算、三点估算</li></ul></li></ol><h3 id="记忆口诀-9" tabindex="-1"><a class="header-anchor" href="#记忆口诀-9"><span>记忆口诀</span></a></h3><p>关键路径最长，浮动时间决定灵活性，赶工加资源快速跟进并行做</p><hr><h2 id="第11章-项目成本管理" tabindex="-1"><a class="header-anchor" href="#第11章-项目成本管理"><span>第11章 项目成本管理</span></a></h2><h3 id="高频考点-11" tabindex="-1"><a class="header-anchor" href="#高频考点-11"><span>高频考点</span></a></h3><ol><li><p><strong>成本估算方法</strong></p><ul><li>类比估算、参数估算、自下而上估算、三点估算</li></ul></li><li><p><strong>挣值管理指标</strong></p><ul><li>CV = EV - AC（成本偏差）</li><li>CPI = EV / AC（成本绩效指数）</li><li>SV = EV - PV（进度偏差）</li><li>SPI = EV / PV（进度绩效指数）</li></ul></li><li><p><strong>成本控制方法</strong></p><ul><li>挣值管理、偏差分析、成本预测</li></ul></li></ol><h3 id="记忆口诀-10" tabindex="-1"><a class="header-anchor" href="#记忆口诀-10"><span>记忆口诀</span></a></h3><p>挣值分析偏差预测，CV SV CPI SPI要记清</p><hr><h2 id="第12章-项目质量管理" tabindex="-1"><a class="header-anchor" href="#第12章-项目质量管理"><span>第12章 项目质量管理</span></a></h2><h3 id="高频考点-12" tabindex="-1"><a class="header-anchor" href="#高频考点-12"><span>高频考点</span></a></h3><ol><li><p><strong>质量控制工具</strong></p><ul><li>因果图、控制图、直方图、帕累托图、散点图、流程图、检查清单</li></ul></li><li><p><strong>质量保证活动</strong></p><ul><li>质量审计、过程改进、质量培训</li></ul></li><li><p><strong>质量规划输出</strong></p><ul><li>质量管理计划、质量测量指标、质量核对单</li></ul></li></ol><h3 id="记忆口诀-11" tabindex="-1"><a class="header-anchor" href="#记忆口诀-11"><span>记忆口诀</span></a></h3><p>控制工具多又多，因果控制直方帕累托，质量保证靠审计</p><hr><h2 id="第13章-项目资源管理" tabindex="-1"><a class="header-anchor" href="#第13章-项目资源管理"><span>第13章 项目资源管理</span></a></h2><h3 id="高频考点-13" tabindex="-1"><a class="header-anchor" href="#高频考点-13"><span>高频考点</span></a></h3><ol><li><p><strong>团队发展阶段</strong></p><ul><li>形成、震荡、规范、执行、解散</li></ul></li><li><p><strong>冲突管理策略</strong></p><ul><li>回避、妥协、强制、合作、缓和</li></ul></li><li><p><strong>资源管理计划内容</strong></p><ul><li>资源需求、资源分配、资源监控</li></ul></li></ol><h3 id="记忆口诀-12" tabindex="-1"><a class="header-anchor" href="#记忆口诀-12"><span>记忆口诀</span></a></h3><p>团队建设五阶段，冲突管理要得当，资源平衡优化监控</p><hr><h2 id="第14章-项目沟通管理" tabindex="-1"><a class="header-anchor" href="#第14章-项目沟通管理"><span>第14章 项目沟通管理</span></a></h2><h3 id="高频考点-14" tabindex="-1"><a class="header-anchor" href="#高频考点-14"><span>高频考点</span></a></h3><ol><li><p><strong>沟通渠道计算</strong></p><ul><li>公式：n(n-1)/2</li></ul></li><li><p><strong>沟通管理计划内容</strong></p><ul><li>沟通目标、对象、内容、方式、频率、责任人</li></ul></li><li><p><strong>绩效报告内容</strong></p><ul><li>进度报告、成本报告、质量报告、风险报告</li></ul></li></ol><h3 id="记忆口诀-13" tabindex="-1"><a class="header-anchor" href="#记忆口诀-13"><span>记忆口诀</span></a></h3><p>渠道数量n方减n除以二，沟通计划六要素，绩效报告多维度</p><hr><h2 id="第15章-项目风险管理" tabindex="-1"><a class="header-anchor" href="#第15章-项目风险管理"><span>第15章 项目风险管理</span></a></h2><h3 id="高频考点-15" tabindex="-1"><a class="header-anchor" href="#高频考点-15"><span>高频考点</span></a></h3><ol><li><p><strong>风险识别方法</strong></p><ul><li>头脑风暴、德尔菲法、检查表、SWOT分析</li></ul></li><li><p><strong>风险应对策略</strong></p><ul><li>规避、转移、减轻、接受</li></ul></li><li><p><strong>风险规划内容</strong></p><ul><li>风险管理策略、风险分类、风险概率和影响定义</li></ul></li></ol><h3 id="记忆口诀-14" tabindex="-1"><a class="header-anchor" href="#记忆口诀-14"><span>记忆口诀</span></a></h3><p>头脑风暴德尔菲，规避转移减轻接受，风险应对四策略</p><hr><h2 id="第16章-项目采购管理" tabindex="-1"><a class="header-anchor" href="#第16章-项目采购管理"><span>第16章 项目采购管理</span></a></h2><h3 id="高频考点-16" tabindex="-1"><a class="header-anchor" href="#高频考点-16"><span>高频考点</span></a></h3><ol><li><p><strong>合同类型</strong></p><ul><li>固定总价合同、成本补偿合同、工时材料合同</li></ul></li><li><p><strong>采购流程</strong></p><ul><li>采购规划、采购实施、合同管理、合同收尾</li></ul></li><li><p><strong>合同收尾步骤</strong></p><ul><li>合同验收、合同结算、合同归档、经验教训总结</li></ul></li></ol><h3 id="记忆口诀-15" tabindex="-1"><a class="header-anchor" href="#记忆口诀-15"><span>记忆口诀</span></a></h3><p>固定总价成本补偿工时材料，验收结算归档合同收尾三步曲</p><hr><h2 id="第17章-项目干系人管理" tabindex="-1"><a class="header-anchor" href="#第17章-项目干系人管理"><span>第17章 项目干系人管理</span></a></h2><h3 id="高频考点-17" tabindex="-1"><a class="header-anchor" href="#高频考点-17"><span>高频考点</span></a></h3><ol><li><p><strong>干系人识别方法</strong></p><ul><li>头脑风暴、专家判断、文档分析、访谈</li></ul></li><li><p><strong>干系人分类（权力-利益矩阵）</strong></p><ul><li>高权力高利益：重点管理</li><li>高权力低利益：满足需求</li><li>低权力高利益：告知信息</li><li>低权力低利益：监督</li></ul></li><li><p><strong>干系人沟通策略</strong></p><ul><li>沟通频率、方式、内容</li></ul></li></ol><h3 id="记忆口诀-16" tabindex="-1"><a class="header-anchor" href="#记忆口诀-16"><span>记忆口诀</span></a></h3><p>识别干系人，权力利益矩阵分类，沟通策略要得当</p><hr><h2 id="第18章-项目绩效域" tabindex="-1"><a class="header-anchor" href="#第18章-项目绩效域"><span>第18章 项目绩效域</span></a></h2><h3 id="高频考点-18" tabindex="-1"><a class="header-anchor" href="#高频考点-18"><span>高频考点</span></a></h3><ol><li><p><strong>五大绩效域</strong></p><ul><li>交付、相关方、变更、规划、风险</li></ul></li><li><p><strong>交付绩效域核心</strong></p><ul><li>范围管理、质量保证、可交付成果管理</li></ul></li><li><p><strong>相关方绩效域核心</strong></p><ul><li>相关方识别、参与、沟通</li></ul></li></ol><h3 id="记忆口诀-17" tabindex="-1"><a class="header-anchor" href="#记忆口诀-17"><span>记忆口诀</span></a></h3><p>绩效域五领域，交付相关方变更规划风险，相互关联保成功</p><hr><h2 id="第19章-配置与变更管理" tabindex="-1"><a class="header-anchor" href="#第19章-配置与变更管理"><span>第19章 配置与变更管理</span></a></h2><h3 id="高频考点-19" tabindex="-1"><a class="header-anchor" href="#高频考点-19"><span>高频考点</span></a></h3><ol><li><p><strong>配置管理内容</strong></p><ul><li>配置项识别、控制、状态报告、审计</li></ul></li><li><p><strong>变更管理流程</strong></p><ul><li>提交、评估、审批、实施、验证</li></ul></li><li><p><strong>版本控制方法</strong></p><ul><li>集中式（SVN）、分布式（Git）</li></ul></li></ol><h3 id="记忆口诀-18" tabindex="-1"><a class="header-anchor" href="#记忆口诀-18"><span>记忆口诀</span></a></h3><p>配置管理管项，变更管理有流程，版本控制保一致</p><hr><h2 id="第20章-高级项目管理" tabindex="-1"><a class="header-anchor" href="#第20章-高级项目管理"><span>第20章 高级项目管理</span></a></h2><h3 id="高频考点-20" tabindex="-1"><a class="header-anchor" href="#高频考点-20"><span>高频考点</span></a></h3><ol><li><p><strong>大型项目特点</strong></p><ul><li>规模大、复杂度高、跨组织、风险高</li></ul></li><li><p><strong>项目集管理</strong></p><ul><li>管理一组相关项目，实现战略目标</li></ul></li><li><p><strong>项目组合管理</strong></p><ul><li>管理组织内所有项目，实现战略目标</li></ul></li></ol><h3 id="记忆口诀-19" tabindex="-1"><a class="header-anchor" href="#记忆口诀-19"><span>记忆口诀</span></a></h3><p>大型项目规模大，项目集管理多项目，项目组合管全部</p><hr><h2 id="第21章-项目管理科学基础" tabindex="-1"><a class="header-anchor" href="#第21章-项目管理科学基础"><span>第21章 项目管理科学基础</span></a></h2><h3 id="高频考点-21" tabindex="-1"><a class="header-anchor" href="#高频考点-21"><span>高频考点</span></a></h3><ol><li><p><strong>三点估算公式</strong></p><ul><li>(乐观时间 + 4×最可能时间 + 悲观时间) / 6</li></ul></li><li><p><strong>经济分析方法</strong></p><ul><li>投资回报率（ROI）、净现值（NPV）、内部收益率（IRR）</li></ul></li><li><p><strong>运筹学方法</strong></p><ul><li>线性规划、决策树、排队论</li></ul></li></ol><h3 id="记忆口诀-20" tabindex="-1"><a class="header-anchor" href="#记忆口诀-20"><span>记忆口诀</span></a></h3><p>三点估算公式要记牢，经济分析看效益，运筹学优化资源</p><hr><h2 id="第22章-组织通用治理" tabindex="-1"><a class="header-anchor" href="#第22章-组织通用治理"><span>第22章 组织通用治理</span></a></h2><h3 id="高频考点-22" tabindex="-1"><a class="header-anchor" href="#高频考点-22"><span>高频考点</span></a></h3><ol><li><p><strong>组织治理内容</strong></p><ul><li>治理结构、决策机制、监督体系、责任体系</li></ul></li><li><p><strong>战略管理流程</strong></p><ul><li>战略分析、战略制定、战略实施、战略评估</li></ul></li><li><p><strong>合规管理内容</strong></p><ul><li>合规风险识别、政策制定、监控、培训</li></ul></li></ol><h3 id="记忆口诀-21" tabindex="-1"><a class="header-anchor" href="#记忆口诀-21"><span>记忆口诀</span></a></h3><p>组织治理定方向，战略管理三步走，合规管理守规矩</p><hr><h2 id="第23章-组织通用管理" tabindex="-1"><a class="header-anchor" href="#第23章-组织通用管理"><span>第23章 组织通用管理</span></a></h2><h3 id="高频考点-23" tabindex="-1"><a class="header-anchor" href="#高频考点-23"><span>高频考点</span></a></h3><ol><li><p><strong>管理职能</strong></p><ul><li>计划、组织、领导、控制</li></ul></li><li><p><strong>人力资源管理内容</strong></p><ul><li>招聘与选拔、培训与发展、绩效管理、薪酬管理</li></ul></li><li><p><strong>财务管理内容</strong></p><ul><li>预算管理、成本控制、财务分析、资金管理</li></ul></li></ol><h3 id="记忆口诀-22" tabindex="-1"><a class="header-anchor" href="#记忆口诀-22"><span>记忆口诀</span></a></h3><p>管理职能四方面，人力资源管人才，财务管理管资金</p><hr><h2 id="第24章-法律法规与标准规范" tabindex="-1"><a class="header-anchor" href="#第24章-法律法规与标准规范"><span>第24章 法律法规与标准规范</span></a></h2><h3 id="高频考点-24" tabindex="-1"><a class="header-anchor" href="#高频考点-24"><span>高频考点</span></a></h3><ol><li><p><strong>相关法律法规</strong></p><ul><li>合同法、招标投标法、政府采购法、著作权法、专利法</li></ul></li><li><p><strong>常见标准</strong></p><ul><li>ISO 9001（质量管理）、ISO 27001（信息安全）、ITIL（IT服务管理）</li></ul></li><li><p><strong>合规管理流程</strong></p><ul><li>合规风险识别、政策制定、培训、监控、改进</li></ul></li></ol><h3 id="记忆口诀-23" tabindex="-1"><a class="header-anchor" href="#记忆口诀-23"><span>记忆口诀</span></a></h3><p>法律法规要遵守，标准规范保质量，合规要求要落实</p>`,144)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};